import {MON_INDEX} from './mon-index.mjs';
import {readFields,updateFields} from './mon-fields.mjs';
import {parseSave,PROFILE,checksum,decodeName} from './core.mjs';
import {readStorage} from './additions.mjs';
import {SPECIES} from './catalog.mjs';
import {STAT_DATA as D} from './stat-data.mjs';
const dv=b=>new DataView(b.buffer,b.byteOffset,b.byteLength);
export const STAT_NAMES=['HP','Attack','Defense','Speed','Sp. Atk','Sp. Def'];
function worldBytes(s){const b=new Uint8Array(13808);let p=0;for(let i=1;i<=4;i++){const n=PROFILE.sizes[i],a=s.active.sections.get(i);b.set(s.bytes.subarray(a,a+n),p);p+=n;}return b;}
export function statContext(input){const s=parseSave(input),w=worldBytes(s),flag=n=>!!(w[D.flagOffset+(n>>3)]&(1<<(n&7))),v=dv(w),variable=n=>v.getUint16(D.varOffset+n*2,true),difficulty=variable(0x407a)&255,badges=flag(0xdee)?18:flag(0xcd4)?17:variable(0x4061)&255,capMode=(2-variable(0x4111))&255;const row=D.caps[difficulty],cap=flag(0xe3a)&&!flag(0x2d)?5:badges===18?100:row&&badges<=18?row[2*19+badges]+row[5*19+badges]:null;return {flag,cap,capEnabled:!!(capMode>difficulty?2:capMode),bonus:[16,17,18,21,19,20].map((i,k)=>1+3*Math.min(s.bytes[s.trainer+D.bonusOffset+i],D.bonusCaps[k]))};}
export function describeMon(raw,location,ctx){const v=dv(raw),species=v.getUint16(28,true)&4095,form=(v.getUint32(28,true)>>>12)&31,meta=D.species[species],mapped=meta?.forms?.[form],statsMeta=D.species[mapped],experience=(v.getUint32(20,true)>>>10)&0x1fffff;let level=0;if(statsMeta){const growth=D.experience[statsMeta.growth];if(growth)for(let n=1;n<=100;n++)if(experience>=growth[n])level=n;}
const nature=(raw[39]>>2)&31;const mon={...location,key:location.destination==='party'?'party:'+location.slot:`pc:${location.box}:${location.slot}`,raw,species,form,mapped,speciesName:MON_INDEX.find(m=>m.id===mapped)?.name||SPECIES[mapped]||SPECIES[species]||`Species ${species}`,nickname:decodeName(raw.subarray(8,20)),level,nature:nature||v.getUint32(0,true)%25,ev:Array.from(raw.subarray(32,38)),egg:!!(raw[39]&128),storedStats:raw.length===76?Array.from({length:6},(_,i)=>v.getUint16(64+i*2,true)):null,hp:raw.length===76?v.getUint16(62,true):null};
Object.assign(mon,readFields(mon,ctx));try{mon.stats=calculateStats(mon,mon.ev,ctx);mon.editable=true}catch(e){mon.stats=mon.storedStats;mon.editable=false;mon.reason=e.message}return mon;}
export function calculateStats(mon,ev,ctx){if(mon.egg)throw Error('ไข่โปเกมอนยังไม่รองรับการแก้ค่าสเตตัส');if(!mon.level||!D.species[mon.mapped]||mon.nature>24)throw Error('ข้อมูลคำนวณสเตตัสของตัวนี้ยังไม่รองรับ');if(ctx.flag(0x3f)||mon.raw[23]&128)throw Error('โหมดปรับสเตตัสพิเศษของตัวนี้ยังไม่รองรับการคำนวณ');let level=mon.level;if(ctx.flag(0x2d)||ctx.flag(0xe3a)||(ctx.capEnabled&&!ctx.flag(0xdee)&&level>=ctx.cap)){if(!ctx.cap)throw Error('รูปแบบ Level Cap นี้ยังไม่รองรับ');level=ctx.cap;}let meta=D.species[mon.mapped],base=(ctx.flag(0x2f)&&meta.alt[0]?meta.alt:meta.base).slice();if(base.some(x=>x<1||x>1000))throw Error('ค่าสเตตัสพื้นฐานไม่ตรงรูปแบบ');const trait=(mon.raw[41]>>4)&7;
const reduce=(i,d)=>base[i]-=Math.floor(base[i]/d),raise=(i,d)=>base[i]+=Math.floor(base[i]/d);
if(trait===1){reduce(1,3);reduce(4,3);raise(3,3)}
if(trait===2){reduce(3,3);raise(2,4);raise(5,4)}
if(trait===3){reduce(2,3);reduce(5,3);raise(1,4);raise(4,4)}
if(trait===4){reduce(2,3);reduce(5,3);raise(3,3)}
if(trait===5){reduce(1,3);reduce(4,3);raise(2,4);raise(5,4)}
if(trait===6){reduce(3,2);raise(1,3);raise(4,3)}
if(trait===7){const avg=Math.floor(base.slice(1).reduce((a,b)=>a+b,0)/5);base=base.map((x,i)=>i?avg:x)}
const effective=ctx.flag(0x40)||ev.reduce((a,b)=>a+b,0)>510?ev.map(()=>0):ev;
return base.map((b,i)=>{if(i===0&&mon.species===292)return 8;const raw=Math.floor((2*b+ctx.bonus[i]+Math.floor(effective[i]/4))*level/100)+(i?5:level+10);return i?Math.floor(raw*(100+10*D.nature[mon.nature][i-1])/100):raw});}
export function inspectRoster(input){const s=parseSave(input),pc=readStorage(input),ctx=statContext(input),count=s.bytes[s.world+0x234];if(count>6)throw Error('จำนวน Party ไม่ถูกต้อง');const party=Array.from({length:6},(_,slot)=>slot<count?describeMon(s.bytes.slice(s.world+0x238+slot*76,s.world+0x238+(slot+1)*76),{destination:'party',slot},ctx):null);const boxes=Array.from({length:21},(_,box)=>Array.from({length:30},(_,slot)=>{const p=4+(box*30+slot)*52,raw=pc.slice(p,p+52);return raw.every(x=>x===0)?null:describeMon(raw,{destination:'pc',box,slot},ctx)}));return {party,boxes,ctx,count};}
export function evForStat(mon,ev,ctx,index,target){if(!Number.isInteger(target)||target<1)throw Error('Stats ต้องเป็นจำนวนเต็มบวก');if(calculateStats(mon,ev,ctx)[index]===target)return ev.slice();const choices=[];for(let n=0;n<=252;n++){const next=ev.slice();next[index]=n;if(next.reduce((a,b)=>a+b,0)<=510&&calculateStats(mon,next,ctx)[index]===target)choices.push(next)}if(!choices.length)throw Error('ค่านี้ทำไม่ได้ด้วย EV ที่เหลือและเลเวลปัจจุบัน');choices.sort((a,b)=>Math.abs(a[index]-ev[index])-Math.abs(b[index]-ev[index]));return choices[0];}
export function editRoster(input,changes){if(!changes?.length)return new Uint8Array(input).slice();const s=parseSave(input),roster=inspectRoster(input),out=s.bytes.slice(),pc=readStorage(input);for(const change of changes){const original=change.destination==='party'?roster.party[change.slot]:change.destination==='pc'?roster.boxes[change.box]?.[change.slot]:null;if(!original||original.key!==change.key||original.egg)throw Error('ช่องโปเกมอนนี้ไม่รองรับการแก้ค่า');const raw=updateFields(original,change,roster.ctx),mon=describeMon(raw,original,roster.ctx),ev=change.ev??mon.ev;if(!Array.isArray(ev)||ev.length!==6||ev.some(n=>!Number.isInteger(n)||n<0||n>252)||ev.reduce((a,b)=>a+b,0)>510)throw Error('EV แต่ละค่า 0–252 และรวมไม่เกิน 510');const recalc=ev.some((n,i)=>n!==original.ev[i])||mon.nature!==original.nature||mon.level!==original.level;if(recalc&&!mon.editable)throw Error(mon.reason);raw.set(ev,32);if(change.destination==='party'){const p=s.world+0x238+change.slot*76;if(recalc){const stats=calculateStats(mon,ev,roster.ctx),v=new DataView(raw.buffer,raw.byteOffset,raw.byteLength);stats.forEach((n,i)=>v.setUint16(64+i*2,n,true));const hp=original.hp===0?0:Math.max(1,Math.min(stats[0],original.hp+stats[0]-original.storedStats[0]));v.setUint16(62,hp,true);}if(change.hp!==undefined){const v=new DataView(raw.buffer,raw.byteOffset,raw.byteLength),max=v.getUint16(64,true);if(!Number.isInteger(change.hp)||change.hp<0||change.hp>max)throw Error('HP ปัจจุบันต้องอยู่ระหว่าง 0 ถึง HP สูงสุด');v.setUint16(62,change.hp,true);}out.set(raw,p);}else pc.set(raw,4+(change.box*30+change.slot)*52);}
let p=0;for(let id=5;id<=13;id++){const n=PROFILE.sizes[id],a=s.active.sections.get(id);out.set(pc.subarray(p,p+n),a);p+=n;}const v=dv(out);for(const id of [1,5,6,7,8,9,10,11,12,13]){const a=s.active.sections.get(id);v.setUint16(a+0xff6,checksum(out,a,PROFILE.sizes[id]),true);}parseSave(out);return out;}
